class User:
    def __init__(self, name: str, email: str, password: str):
        self.userID = "firebase generates ID"
        self.name = name
        self.email = email
        self.password = password
        self.familyGroupID = ""

    #CHECK IF EMAIL AND PASSWORD IS BLANK
    def register(self):
        if self.email or self.password == "":
            print("Email and Password cannot be blank")
            return
        return self
    
    #CHECK IF EMAIL AND PASSWORD ARE NOT BLANK 
    def login(self):
        if self.email or self.password == "":
            print("Email and Password cannot be blank")
            return
        return self
    
    #LOGS OUT
    def logout(self):
        self.familyGroupID = ""


