class GroceryItem:
    def __init__(self, name: str, addedBy: str, familyGroupID: str, isPurchased: bool):
        self.itemID = "generated by firebase"
        self.name = name
        self.addedBy = addedBy
        self.familyGroupID = familyGroupID
        self.isPurchased = False

    #ADDS ITEM
    def addItem(self):
        if self.name == "":
            return "Item name cannot be blank"
        else:
            return self
        
    #UPDATES NAME
    def updateName(self, newName):
        if newName == "":
            return "Item name cannot be blank"
        else:
            self.name = newName
        
    
    #DELETES ITEM
    def deleteItem(self):
        self.name = ""
        self.isPurchased = False
        self.addedBy = ""

    #MARKS AS PURCHASED
    def markAsPurchased(self):
        self.isPurchased = not self.isPurchased

    #SORTS WETHER ITEM IS PURCHASED
    def sortByPurchased(self):
        stillNeeded = []
        alreadybought = []
        for i in GroceryItems:
            if i == False:
                stillNeeded.append(i)
            else:
                alreadybought.append(i)
        return stillNeeded + alreadybought